changeSet.sql:
CREATE TABLE pkm_operations (
    id                  BIGSERIAL PRIMARY KEY,
    pkm_id              BIGINT NOT NULL REFERENCES pkm_documents(id) ON DELETE CASCADE,
    system_type         VARCHAR(200),
    position            INT,
    category            VARCHAR(200),   -- Обязательные / Рекомендуемые
    operation_name      TEXT NOT NULL,  -- «Техническое обслуживание устройства контроля доступа»
    work_composition    TEXT,           -- состав работ (пункты)
    periodicity         VARCHAR(200),   -- как в регламенте: «Ежемесячно», «Два раза в год»
    periodicity_per_year NUMERIC(6,2)   -- нормализовано: 12, 4, 2, 1 …
);
CREATE INDEX idx_pkm_ops_pkm ON pkm_operations(pkm_id);
CREATE INDEX idx_pkm_ops_system ON pkm_operations(system_type);
